package studio.startapps.pandemona.feed.mobile;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageImpl;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import studio.startapps.pandemona.core.AbstractControllerTest;
import studio.startapps.pandemona.core.ControllerTest;
import studio.startapps.pandemona.feed.internal.FeedService;
import studio.startapps.pandemona.feed.internal.Post;

import java.time.LocalDateTime;
import java.util.List;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@ControllerTest(FeedMobileController.class)
class FeedMobileControllerTest extends AbstractControllerTest {

    @MockitoBean
    FeedService feedService;

    private ObjectMapper objectMapper = new ObjectMapper();

    @DisplayName("Fetch feed v2 should be ok")
    @Test
    void fetchFeedV2ShouldBeOk() throws Exception {
        List<Post> post = List.of(
                Post.builder()
                        .id(1L)
                        .authorName("ONPM")
                        .authorPicture("data:image/png;base64,")
                        .content(objectMapper.readTree("""
                                        {
                                        "fr": "Bienvenu sur Pharmada!",
                                        "mg": "Tongasoa!"
                                        }"""))
                        .mediaList(objectMapper.readTree("""
                                ["data:image/png;base64,"]
                                """))
                        .publishedOn(LocalDateTime.of(2026, 1, 1, 8, 55))
                        .build()
        );

        Page<Post> postPage = new PageImpl<>(post);
        when(feedService.findAll(any())).thenReturn(postPage);

        mockMvc.perform(
                get("/api/mobile/feed")
                        .header("X-Api-Version", "2.0")
        ).andExpect(status().isOk())
                .andExpect(content().json("""
                        {
                            "data": [{
                                "id": 1,
                                "authorName": "ONPM",
                                "authorPicture": "data:image/png;base64,",
                                "content": {
                                    "fr": "Bienvenu sur Pharmada!",
                                    "mg": "Tongasoa!"
                                },
                                "mediaList": [
                                    "data:image/png;base64,"
                                ],
                                "publishedOn": "2026-01-01T08:55:00"
                            }],
                            "last": true
                        }"""));
    }
}
